set -eu
cat > /etc/nginx/conf.d/port6700.conf <<'ANTRIEB_NGINX_EOF'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;

    location / {
        default_type text/plain;
        return 200 "nginx on node1 port 6700\n";
    }
}
ANTRIEB_NGINX_EOF
nginx -t

